#!/usr/bin/env node
// Copies the shared dictionaries and i18n core from the web app into the mobile app, so both apps
// speak with the same keys and the same Bangla. Edit apps/web/src/i18n/{en,bn,core}.ts, then run:
//   pnpm --dir apps/mobile i18n        (or: node apps/mobile/scripts/sync-i18n.mjs)
// The copies in apps/mobile/src/i18n/ are generated: do not edit them by hand.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const from = join(here, "../../web/src/i18n");
const to = join(here, "../src/i18n");
const banner = "// GENERATED by apps/mobile/scripts/sync-i18n.mjs from apps/web/src/i18n. Edit the web copy, then re-run the script.\n";

for (const f of ["en.ts", "bn.ts", "core.ts"]) {
  writeFileSync(join(to, f), banner + readFileSync(join(from, f), "utf8"));
  console.log("synced", f);
}

// Category icon paths (apps/web/src/lib/categoryIcons.ts), drawn in the app by components/CategoryIcon.tsx.
writeFileSync(
  join(here, "../src/lib/categoryIcons.ts"),
  "// GENERATED by apps/mobile/scripts/sync-i18n.mjs from apps/web/src/lib/categoryIcons.ts. Edit the web copy, then re-run the script.\n" +
    readFileSync(join(here, "../../web/src/lib/categoryIcons.ts"), "utf8"),
);
console.log("synced categoryIcons.ts");

// Photo resizing rules (apps/web/src/lib/img.ts): the app asks the stores' image servers for the size it shows.
writeFileSync(
  join(here, "../src/lib/img.ts"),
  "// GENERATED by apps/mobile/scripts/sync-i18n.mjs from apps/web/src/lib/img.ts. Edit the web copy, then re-run the script.\n" +
    readFileSync(join(here, "../../web/src/lib/img.ts"), "utf8"),
);
console.log("synced img.ts");

// Size charts (apps/web/src/lib/sizeGuide.ts), shown by components/product/SizeGuide.tsx.
writeFileSync(
  join(here, "../src/lib/sizeGuide.ts"),
  "// GENERATED by apps/mobile/scripts/sync-i18n.mjs from apps/web/src/lib/sizeGuide.ts. Edit the web copy, then re-run the script.\n" +
    readFileSync(join(here, "../../web/src/lib/sizeGuide.ts"), "utf8"),
);
console.log("synced sizeGuide.ts");
